style.css:
@-moz-document domain("signalwire.com") {
/* General Backgrounds */
    body, html, #app, .app-container, .main-content, .page-wrapper {
        background-color: #000000 !important;
        color: #e0e0e0 !important; /* Lighter text for contrast */
    }

    /* Card and Panel Backgrounds */
    .card, .panel, .bg-white, .modal-content, .dropdown-menu {
        background-color: #000000 !important;
        border-color: #1a1a1a !important;
    }

    /* Text Colors */
    h1, h2, h3, h4, h5, h6, p, span, div, a:not(.btn), label, strong, em {
        color: #e0e0e0 !important;
    }

    /* Links and Buttons (adjust as needed for specific states) */
    a {
        color: #4CAF50 !important; /* Example link color */
    }
    a:hover {
        color: #66BB6A !important;
    }

    .btn-primary, .btn-success {
        background-color: #4CAF50 !important;
        border-color: #4CAF50 !important;
        color: #ffffff !important;
    }
    .btn-primary:hover, .btn-success:hover {
        background-color: #66BB6A !important;
        border-color: #66BB6A !important;
    }

    .btn-secondary, .btn-outline-secondary {
        background-color: #333333 !important;
        border-color: #444444 !important;
        color: #e0e0e0 !important;
    }
    .btn-secondary:hover, .btn-outline-secondary:hover {
        background-color: #444444 !important;
        border-color: #555555 !important;
    }

    /* Input Fields */
    input[type="text"], input[type="email"], input[type="password"], textarea, select {
        background-color: #0d0d0d !important;
        border: 1px solid #333333 !important;
        color: #e0e0e0 !important;
    }
    input[type="text"]:focus, input[type="email"]:focus, input[type="password"]:focus, textarea:focus, select:focus {
        border-color: #4CAF50 !important;
        box-shadow: 0 0 0 0.2rem rgba(76, 175, 80, 0.25) !important;
    }

    /* Table Styles */
    table {
        background-color: #000000 !important;
    }
    th, td {
        border-color: #1a1a1a !important;
        color: #e0e0e0 !important;
    }
    thead th {
        background-color: #111111 !important;
    }
    tbody tr:nth-child(even) {
        background-color: #050505 !important;
    }
    tbody tr:nth-child(odd) {
        background-color: #000000 !important;
    }

    /* Navigation Bars and Sidebars */
    .navbar, .sidebar, .left-sidebar, .top-navbar {
        background-color: #0a0a0a !important;
        border-color: #1a1a1a !important;
    }

    .nav-link, .sidebar-link {
        color: #b0b0b0 !important;
    }
    .nav-link:hover, .sidebar-link:hover, .nav-link.active, .sidebar-link.active {
        background-color: #1a1a1a !important;
        color: #ffffff !important;
    }

    /* Scrollbars (Webkit only) */
    ::-webkit-scrollbar {
        width: 8px;
        height: 8px;
    }
    ::-webkit-scrollbar-track {
        background: #000000;
    }
    ::-webkit-scrollbar-thumb {
        background: #333333;
        border-radius: 4px;
    }
    ::-webkit-scrollbar-thumb:hover {
        background: #555555;
    }

    /* Hide Logos and Branding */
    /* These selectors are guesses and might need adjustment based on SignalWire's current HTML structure */
    img[src*="logo"],
    img[alt*="logo"],
    .brand-logo,
    .navbar-brand,
    .sidebar-header .logo,
    .footer-logo,
    [class*="logo"] { /* More general attempt, be careful with this one */
        display: none !important;
    }

    /* Also attempt to hide text-based branding if present */
    .brand-text,
    .logo-text,
    .signalwire-branding {
        display: none !important;
    }
}
